        setSelectedUserId(log.user_id)
        setUserInfoDialogOpen(true)
      }}
    >
      <Avatar className='ring-border/60 size-6 shrink-0 ring-1'>
        <AvatarFallback
          className={cn(
            'text-[11px] font-semibold',
